repo.bookings.py:
"""Booking records."""


class Booking:
    def __init__(self, hotel, nights):
        self.hotel = hotel
        self.nights = nights

    def __repr__(self):
        return "Booking(%r, %r)" % (self.hotel, self.nights)


ROWS = [('lodge', 41), ('lodge', 30), ('grand', 51), ('plaza', 4), ('lodge', 29), ('plaza', 50), ('plaza', 35)]


def load_bookings():
    """Yield the stored bookings one at a time."""
    for hotel, nights in ROWS:
        yield Booking(hotel, nights)

repo.settle.py:
"""Checking that bookings add up."""


def is_settled(bookings, expected_total):
    """Return True when the nights of the bookings add up to expected_total. nights may be fractional."""
    return sum(x.nights for x in bookings) == expected_total


def shortfall(bookings, expected_total):
    """Return how much nights is still missing, never less than 0."""
    return max(0, expected_total - sum(x.nights for x in bookings))


def hotel_names(bookings):
    """Return the distinct hotel values, in first-seen order."""
    names = []
    for x in bookings:
        if x.hotel not in names:
            names.append(x.hotel)
    return names

